CREATE OR REPLACE FUNCTION public.smart_alert_allowed_event(t uuid,ident uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM alert_events a WHERE a.tenant_id=t AND a.id=ident AND smart_alert_can_read(t,a.venue_id,a.area) AND NOT EXISTS(SELECT 1 FROM alert_mutes m WHERE m.tenant_id=t AND m.active AND m.scope='route_to_role' AND (m.kind IS NULL OR m.kind=a.kind) AND (m.area IS NULL OR m.area=a.area) AND (m.venue_id IS NULL OR m.venue_id=a.venue_id) AND (m.created_by=auth.uid() OR NOT EXISTS(SELECT 1 FROM tenant_members tm WHERE tm.tenant_id=t AND tm.user_id=auth.uid() AND tm.role=m.target_role)))) $$;
REVOKE ALL ON FUNCTION public.smart_alert_allowed_event(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.smart_alert_allowed_event(uuid,uuid) TO authenticated;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.smart_alert_action(uuid,uuid,text,jsonb)'::regprocedure) INTO def;
def:=replace(def,'IF a.id IS NULL OR a.kind IS NULL OR NOT smart_alert_can_read(t,a.venue_id,a.area) THEN','IF a.id IS NULL OR a.kind IS NULL OR NOT smart_alert_allowed_event(t,ident) THEN');
def:=replace(def,'IF decision=''yes'' THEN','IF decision=''yes'' THEN
IF EXISTS(SELECT 1 FROM sales_records s WHERE s.tenant_id=t AND (s.venue_id=a.venue_id OR s.venue=(SELECT name FROM venues WHERE id=a.venue_id)) AND s.date >= a.payload->>''start_date'' AND s.date <= vday::text AND extract(dow FROM s.date::date)::int IN (SELECT value::int FROM jsonb_array_elements_text(a.payload->''weekdays''))) THEN RAISE EXCEPTION ''Sales arrived since this question. Refresh Alerts.''; END IF;');
def:=replace(def,'INSERT INTO alert_mutes(tenant_id,kind,venue_id,scope,until_date,reason,created_by) VALUES(t,a.kind,a.venue_id,''until'',vday+15,''Not sure'',auth.uid()); UPDATE alert_events SET status=''muted'',updated_at=now() WHERE id=ident;', 'INSERT INTO alert_mutes(tenant_id,kind,venue_id,scope,until_date,reason,created_by) VALUES(t,a.kind,a.venue_id,''until'',vday+15,''Not sure'',auth.uid()); UPDATE alert_events SET status=''muted'',payload=payload||jsonb_build_object(''snoozed_until'',vday+15),updated_at=now() WHERE id=ident;'); EXECUTE def; END $$;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.smart_alert_unmute(uuid,uuid)'::regprocedure) INTO def;def:=replace(def,'IF m.id IS NULL THEN','IF m.id IS NULL OR NOT smart_alert_can_read(t,m.venue_id,coalesce(m.area,CASE WHEN m.kind LIKE ''sales%'' OR m.kind IN (''missing_sales'',''closed_weekday_question'') THEN ''sales'' WHEN m.kind LIKE ''%bill%'' THEN ''expenses'' WHEN m.kind LIKE ''%bank%'' THEN ''bank'' WHEN m.kind LIKE ''%card%'' THEN ''payments'' WHEN m.kind=''supplier_price_rise'' THEN ''procurement'' ELSE ''finance'' END)) THEN');EXECUTE def;END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.smart_alert_sync(uuid,date,jsonb)'::regprocedure) INTO def;def:=replace(def,'payload=c->''payload'',status=st','payload=coalesce(old.payload,''{}''::jsonb)||coalesce(c->''payload'',''{}''::jsonb),action_path=c->>''action_path'',status=st'); EXECUTE def; END $$;